// === data-loader.js ===
// Shared Data Loader - caches all JSON fetches
(function () {
    'use strict';
    const cache = {};
    const basePath = window.location.pathname.includes('/skywireneo.github.io') ? '/skywireneo.github.io' : '';

    async function loadJSON(filename) {
        if (cache[filename]) return cache[filename];
        try {
            const res = await fetch(`${basePath}/_data/${filename}`);
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            cache[filename] = await res.json();
            return cache[filename];
        } catch (e) {
            console.error(`[DataLoader] Failed to load ${filename}:`, e);
            return null;
        }
    }

    // Convenience methods
    window.DataLoader = {
        getAbout: () => loadJSON('about.json'),
        getContacts: () => loadJSON('contacts.json'),
        getTechnologies: () => loadJSON('technologies.json'),
        getProjects: () => loadJSON('projects.json'),
        getExperience: () => loadJSON('experience.json'),
        getFaq: () => loadJSON('faq.json'),
        getTimeStatus: () => loadJSON('time-status.json'),
        load: loadJSON,
        getCache: () => ({ ...cache })
    };
})();


// === preloader.js ===
/**
 * Preloader - SkyWireNEO
 * Плавный экран загрузки с анимацией текста
 * Настройки загружаются из _data/preloader.json

 */

(function () {
    'use strict';

    const preloader = document.getElementById('preloader');
    if (!preloader) return;

    let config = null;

    let startTime = Date.now();
    let isLoaded = false;

    /**
     * Load configuration from JSON - ONLY source of settings
     */
    async function loadConfig() {
        try {
            // Get base path for GitHub Pages compatibility
            const basePath = window.location.pathname.includes('/skywireneo.github.io')
                ? '/skywireneo.github.io'
                : '';
            const response = await fetch(`${basePath}/_data/preloader.json`);

            if (response.ok) {
                config = await response.json();
            } else {
                console.error('Preloader: failed to load config, response not OK');
            }
        } catch (error) {
            console.error('Preloader: failed to load config', error);
        }
    }



    /**
     * Скрыть preloader с анимацией
     */
    function hidePreloader() {
        // Use config from JSON only - no hardcoded defaults
        const timing = config?.timing || {};
        const minDisplayTime = timing.minDisplayTime || 1000;
        const exitDelay = timing.exitDelay || 500;
        const exitDuration = timing.exitDuration || 600;

        const elapsed = Date.now() - startTime;
        const remainingTime = Math.max(0, minDisplayTime - elapsed);
        const totalDelay = remainingTime + exitDelay;

        setTimeout(() => {
            preloader.classList.add('exiting');

            setTimeout(() => {
                preloader.classList.add('hidden');

                setTimeout(() => {
                    if (preloader.parentNode) {
                        preloader.parentNode.removeChild(preloader);
                    }
                    document.dispatchEvent(new CustomEvent('preloaderComplete'));
                }, 100);

            }, exitDuration);

        }, totalDelay);
    }


    /**
     * Обработчик полной загрузки страницы
     */
    function onPageLoad() {
        if (isLoaded) return;
        isLoaded = true;
        hidePreloader();
    }

    // Apply settings from data-* attributes + JSON config
    function applyPreloaderConfig() {
        const preloaderEl = document.getElementById('preloader');
        if (!preloaderEl) return;

        // CSS Custom Properties from data-*
        const root = document.documentElement;
        root.style.setProperty('--preloader-gradient-start', preloaderEl.dataset.gradientStart);
        root.style.setProperty('--preloader-gradient-end', preloaderEl.dataset.gradientEnd);

        // Toggle visibility based on data-show-*
        const showProgress = preloaderEl.dataset.showProgressBar !== 'false';
        const showPageName = preloaderEl.dataset.showPageName !== 'false';
        const showLoadingText = preloaderEl.dataset.showLoadingText !== 'false';

        const progressLine = preloaderEl.querySelector('.preloader-line');
        const pageName = preloaderEl.querySelector('.preloader-page-name');
        const loadingText = preloaderEl.querySelector('.preloader-loading-text');

        if (progressLine) progressLine.style.display = showProgress ? 'block' : 'none';
        if (pageName) pageName.style.display = showPageName ? 'block' : 'none';
        if (loadingText) loadingText.style.display = showLoadingText ? 'flex' : 'none';
    }

    // Initialize
    loadConfig().then(() => {
        applyPreloaderConfig(); // Apply data-* settings immediately

        // Config loaded, now wait for page load
        if (document.readyState === 'complete') {
            onPageLoad();
        } else {
            window.addEventListener('load', onPageLoad);
            const reserveTimeout = config?.timing?.reserveTimeout || 5000;
            setTimeout(onPageLoad, reserveTimeout);
        }
    });

    // Public API
    window.SkyWirePreloader = {
        hide: hidePreloader,
        isActive: () => !preloader.classList.contains('hidden'),
        getConfig: () => config
    };

})();


// === theme.js ===
// Theme toggle functionality
const body = document.body;
const toggleBtn = document.getElementById('themeToggle');

// Load saved theme
const savedTheme = localStorage.getItem('theme') || 'dark';
body.setAttribute('data-theme', savedTheme);
updateButton(savedTheme);

function updateButton(theme) {
    toggleBtn.innerHTML = theme === 'light'
        ? '<i class="fas fa-moon"></i> Тёмная тема'
        : '<i class="fas fa-sun"></i> Светлая тема';
}

toggleBtn.addEventListener('click', () => {
    const next = body.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
    body.setAttribute('data-theme', next);
    localStorage.setItem('theme', next);
    updateButton(next);
});


// === navigation.js ===
// Sticky navigation + Mobile hamburger menu
const stickyNav = document.getElementById('stickyNav');
const mobileMenuToggle = document.getElementById('mobileMenuToggle');
const mobileMenu = document.getElementById('mobileMenu');
const mobileMenuClose = document.getElementById('mobileMenuClose');
const mobileMenuOverlay = document.getElementById('mobileMenuOverlay');

let lastScrollY = window.scrollY;

// Mobile menu toggle
function toggleMobileMenu() {
    stickyNav.classList.toggle('mobile-menu-open');
    mobileMenu.classList.toggle('active');
    mobileMenuOverlay.classList.toggle('active');
    mobileMenuToggle.classList.toggle('active');
    document.body.classList.toggle('no-scroll');
}

// Event listeners
if (mobileMenuToggle) {
    mobileMenuToggle.addEventListener('click', toggleMobileMenu);
}

if (mobileMenuClose) {
    mobileMenuClose.addEventListener('click', toggleMobileMenu);
}

if (mobileMenuOverlay) {
    mobileMenuOverlay.addEventListener('click', toggleMobileMenu);
}

// Mobile nav links
document.querySelectorAll('.mobile-nav-link').forEach(link => {
    link.addEventListener('click', () => {
        toggleMobileMenu();
    });
});

// Close mobile menu on resize to desktop
window.addEventListener('resize', () => {
    if (window.innerWidth > 768) {
        stickyNav.classList.remove('mobile-menu-open');
        mobileMenu.classList.remove('active');
        mobileMenuOverlay.classList.remove('active');
        mobileMenuToggle.classList.remove('active');
        document.body.classList.remove('no-scroll');
    }
});

window.addEventListener('scroll', () => {
    const currentScrollY = window.scrollY;

    // Show sticky nav after scrolling down 300px
    if (currentScrollY > 300) {
        stickyNav.classList.add('visible');
    } else {
        stickyNav.classList.remove('visible');
    }

    lastScrollY = currentScrollY;
});

// Smooth scroll for navigation links
document.querySelectorAll('.sticky-nav a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
            target.scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });
        }
    });
});

// Progress bar
const progressBar = document.getElementById('progressBar');

window.addEventListener('scroll', () => {
    const scrollTop = window.scrollY;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const scrollPercent = (scrollTop / docHeight) * 100;
    progressBar.style.width = scrollPercent + '%';
});

// Scroll to top button
const scrollToTopBtn = document.getElementById('scrollToTop');

window.addEventListener('scroll', () => {
    if (window.scrollY > 500) {
        scrollToTopBtn.classList.add('visible');
    } else {
        scrollToTopBtn.classList.remove('visible');
    }
});

scrollToTopBtn.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
});

// Extra experience accordion
(function () {
    const accordionHeader = document.querySelector('.accordion-item');
    const accordionContent = document.getElementById('extra-content');
    const accordionIcon = document.querySelector('.accordion-icon');
    if (accordionHeader && accordionContent && accordionIcon) {
        accordionHeader.addEventListener('click', function () {
            const isOpen = accordionContent.classList.contains('active');
            accordionContent.classList.toggle('active');
            accordionIcon.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
        });
    }
})();


// === animations.js ===
// Intersection Observer for scroll animations
const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -20px 0px'  /* Уменьшено для мобильных: -50px → -20px */
};

const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add('visible');
        }
    });
}, observerOptions);

document.querySelectorAll('.animate-on-scroll').forEach(el => {
    observer.observe(el);
});


// === active-nav.js ===
/* ============================================
   ACTIVE SECTION INDICATOR
   ============================================ */

class ActiveSectionIndicator {
    constructor() {
        this.nav = document.getElementById('stickyNav');
        this.links = this.nav ? this.nav.querySelectorAll('a[href^="#"]') : [];
        this.sections = [];
        this.currentActive = null;

        this.init();
    }

    init() {
        if (this.links.length === 0) return;

        // Get all sections that correspond to nav links
        this.links.forEach(link => {
            const targetId = link.getAttribute('href');
            const section = document.querySelector(targetId);
            if (section) {
                this.sections.push({
                    id: targetId,
                    element: section,
                    link: link
                });
            }
        });

        // Bind scroll event with throttling
        this.throttledUpdate = this.throttle(() => this.updateActiveSection(), 100);
        window.addEventListener('scroll', this.throttledUpdate);

        // Initial check
        this.updateActiveSection();
    }

    updateActiveSection() {
        const scrollPos = window.scrollY + 150; // Offset for sticky nav

        // Find current section
        let current = null;

        for (let i = this.sections.length - 1; i >= 0; i--) {
            const section = this.sections[i];
            const sectionTop = section.element.offsetTop;

            if (scrollPos >= sectionTop) {
                current = section;
                break;
            }
        }

        // Update active state
        if (current && current.id !== this.currentActive) {
            // Remove active from all
            this.links.forEach(link => {
                link.classList.remove('active');
            });

            // Add active to current
            current.link.classList.add('active');
            this.currentActive = current.id;
        }
    }

    throttle(func, limit) {
        let inThrottle;
        return function () {
            const args = arguments;
            const context = this;
            if (!inThrottle) {
                func.apply(context, args);
                inThrottle = true;
                setTimeout(() => inThrottle = false, limit);
            }
        };
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new ActiveSectionIndicator();
});


